window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-af4009519ca375b6"]={"versions": [{"id": "FIG-af4009519ca375b6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm der AUTOSAR-Methodik (SPEM-basiert). Das Diagramm spezifiziert die methodische Entwurfsaktivität „Define Signal PDUs“ innerhalb des Systemdesigns der AUTOSAR Classic Platform und ordnet ihr die beteiligte Rolle sowie die erforderlichen Eingangs- und Ausgangs-Artefakte zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>System Engineer</code> (führt die Aktivität mit Multiplizität 1 über eine «performs»-Beziehung aus).\n</li><li><strong>Aktivität</strong>: <code>Define Signal PDUs</code> (zentrale Transformationsaufgabe).\n</li><li><strong>Eingangs-Artefakte («input», jeweils Kardinalität 1)</strong>:\n<ul class=\"fig-list\"><li><code>Data Mapping</code>\n</li><li><code>Mapping of Software Components to ECUs</code>\n</li><li><code>System Signal</code>\n</li><li><code>Topology</code>\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt («output»)</strong>:\n<ul class=\"fig-list\"><li><code>Interaction Layer</code> (Signal-PDU-Definitionen und Kommunikationskonfiguration).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>System Engineer</code> initiiert und führt den Prozessschritt <code>Define Signal PDUs</code> aus. Als Arbeitsgrundlage werden vier Artefakte konsolidiert eingelesen: die Netzwerk- und Bus-Topologie (<code>Topology</code>), die systemspezifischen Signale (<code>System Signal</code>), die Verteilung der Softwarekomponenten auf die Steuergeräte (<code>Mapping of Software Components to ECUs</code>) sowie die Zuordnung von Signalen zu Datenelementen (<code>Data Mapping</code>). Basierend auf diesen Eingangsdaten bündelt die Aktivität Signale zu Signal-PDUs und generiert das Artefakt <code>Interaction Layer</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine verbindliche Entwurfsphase der AUTOSAR-Methodik bei der Netzwerkauslegung. Die Zuordnung von Signalen zu PDUs setzt voraus, dass ECU-Mapping, Daten-Mapping und Topologie bereits spezifiziert sind. Das resultierende Artefakt <code>Interaction Layer</code> bildet die Grundlage für die nachgelagerte PDU- und Frame-Konfiguration im Kommunikations-Stack (z. B. COM / PduR).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4e9a34f7d37e0ac8", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm der AUTOSAR-Methodik (SPEM-basiert). Das Diagramm spezifiziert die methodische Entwurfsaktivität „Define Signal PDUs“ innerhalb des Systemdesigns der AUTOSAR Classic Platform und ordnet ihr die beteiligte Rolle sowie die erforderlichen Eingangs- und Ausgangs-Artefakte zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>System Engineer</code> (führt die Aktivität mit Multiplizität 1 über eine «performs»-Beziehung aus).\n</li><li><strong>Aktivität</strong>: <code>Define Signal PDUs</code> (zentrale Transformationsaufgabe).\n</li><li><strong>Eingangs-Artefakte («input», jeweils Kardinalität 1)</strong>:\n<ul class=\"fig-list\"><li><code>Data Mapping</code>\n</li><li><code>Mapping of Software Components to ECUs</code>\n</li><li><code>System Signal</code>\n</li><li><code>Topology</code>\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt («output»)</strong>:\n<ul class=\"fig-list\"><li><code>Interaction Layer</code> (Signal-PDU-Definitionen und Kommunikationskonfiguration).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>System Engineer</code> initiiert und führt den Prozessschritt <code>Define Signal PDUs</code> aus. Als Arbeitsgrundlage werden vier Artefakte konsolidiert eingelesen: die Netzwerk- und Bus-Topologie (<code>Topology</code>), die systemspezifischen Signale (<code>System Signal</code>), die Verteilung der Softwarekomponenten auf die Steuergeräte (<code>Mapping of Software Components to ECUs</code>) sowie die Zuordnung von Signalen zu Datenelementen (<code>Data Mapping</code>). Basierend auf diesen Eingangsdaten bündelt die Aktivität Signale zu Signal-PDUs und generiert das Artefakt <code>Interaction Layer</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine verbindliche Entwurfsphase der AUTOSAR-Methodik bei der Netzwerkauslegung. Die Zuordnung von Signalen zu PDUs setzt voraus, dass ECU-Mapping, Daten-Mapping und Topologie bereits spezifiziert sind. Das resultierende Artefakt <code>Interaction Layer</code> bildet die Grundlage für die nachgelagerte PDU- und Frame-Konfiguration im Kommunikations-Stack (z. B. COM / PduR).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-af4009519ca375b6", "to": "FIG-4e9a34f7d37e0ac8", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
